package com.saludintegral.medico.services;
import org.springframework.stereotype.Service; import java.util.*; import com.saludintegral.medico.model.*; import com.saludintegral.medico.repository.*; import com.saludintegral.medico.dto.*;
@Service public class MedicoService {final MedicoRepository m;final EspecialidadRepository e; public MedicoService(MedicoRepository m,EspecialidadRepository e){this.m=m;this.e=e;} public List<Medico> all(){return m.findAll();} public Medico get(Long id){return m.findById(id).orElseThrow(()->new NoSuchElementException("Médico no encontrado: "+id));} public Medico save(MedicoRequest x){if(!e.existsById(x.idEspecialidad()))throw new NoSuchElementException("Especialidad no encontrada");Medico a=new Medico();a.cmp=x.cmp();a.nombres=x.nombres();a.apellidos=x.apellidos();a.telefono=x.telefono();a.correo=x.correo();a.idEspecialidad=x.idEspecialidad();a.estado=x.estado()==null?"A":x.estado();return m.save(a);} public Medico update(Long id,MedicoRequest x){Medico a=get(id);if(!e.existsById(x.idEspecialidad()))throw new NoSuchElementException("Especialidad no encontrada");a.cmp=x.cmp();a.nombres=x.nombres();a.apellidos=x.apellidos();a.telefono=x.telefono();a.correo=x.correo();a.idEspecialidad=x.idEspecialidad();if(x.estado()!=null)a.estado=x.estado();return m.save(a);} public void delete(Long id){m.delete(get(id));} public List<Especialidad> especialidades(){return e.findAll();} public Especialidad crearEspecialidad(EspecialidadRequest x){Especialidad a=new Especialidad();a.nombre=x.nombre();a.descripcion=x.descripcion();a.estado=x.estado()==null?"A":x.estado();return e.save(a);} }
